\label{def:proptheory}
		Let $\mathbb{T}$ be a geometric theory. If its signature has no sorts [so there can be no variables or terms, nor existential quantification],
		then we call $\mathbb{T}$ a \emph{propositional theory}.

\label{def:apartness}
		Given two Dedekind reals $x$ and $y$, we denote:
		\begin{itemize}
			\item  $x<y$ if there exists some rational number $q$ such that $x<q<y$. In particular, this defines a strict order on $\mathbb{R}$, and the space of all pairs of Dedekinds satisfying
			$x<y$ defines an open subspace of $\mathbb{R}\times\mathbb{R}$.
			\item $x\geq y$ if $(x,y)$ belongs to the closed complement of  $<$ in $\mathbb{R}\times\mathbb{R}$.
		\end{itemize}

There exist natural maps
		\begin{align*}
		L\colon \mathbb{R} &\longrightarrow \overrightarrow{(-\infty,\infty]}\\
		R\colon \mathbb{R} &\longrightarrow \overleftarrow{[-\infty,\infty)}
		\end{align*}
		where given a Dedekind real $x=(L_x,R_x)$, $L$ sends $x\mapsto L_x$ and $R$ sends $x\mapsto R_x$.

\label{lem:check1sided} The following are equivalent for Dedekinds $x,y$:
		\begin{enumerate}
			\item $x\leq y$
			\item $L_x\sqsubseteq L_y$
			\item $R_x\sqsupseteq R_y$
		\end{enumerate}
		\begin{proof} $(1)\Rightarrow (2)$:  Suppose $q<L_x$. By roundedness, we can find $q'\in\mathbb{Q}$ such that $q<q'<L_x$. By locatedness, either $q<L_y$ or $ R_y<q'$. If $q<L_y$, then done; else if $R_y<q'$, then $y<x$, contradicting (1).

			$(2)\Rightarrow (1)$: Suppose for contradiction that there exists some $q$ such that $y<q<x$. This means there exists $q\in L_x$ and $q\notin L_y$, contradicting (2). Since (2) implies that $y<x$ does not hold, and $x\leq y$ is the closed complement of $y<x$, this implies (1).

			$(1)\Leftrightarrow (3)$: Analogous to above.
		\end{proof}

\label{cor:check1sided} The following are equivalent for Dedekinds $x,y$:
		\begin{enumerate}
			\item $x=y$
			\item $L_x=L_y$
			\item $R_x=R_y$.
		\end{enumerate}

\label{lem:rationalsliftreals} We work in the category \textbf{Spaces}. Given an $R$-structure $(Y,<)$, there exists a surjection $\phi\colon Y\rightarrow \mathsf{RIdl}(Y,<)$, composition with which induces an equivalence between:
		\begin{itemize}
			\item Maps $\overline{f}\colon \mathsf{RIdl}(Y,<)\rightarrow X$
			\item Maps $f\colon Y\rightarrow X$ satisfying the following two lifting conditions for all $q,q'\in Y$:
			\begin{enumerate}[label={(\roman*)}]
				\item \emph{\textbf{(Monotonicity)}}  $q'<q \implies f(q')\sqsubseteq f(q)$.
				\item \emph{\textbf{(Continuity)}} $f(q)=\displaystyle\!\operatorname*{\,\ThisStyle{\ensurestackMath{ 
			\bigsqcup\stackengine{-0pt}{\!}{\SavedStyle\!^{\mathord{\uparrow}}}{O}{l}{F}{T}{S}}}\,}_{q'
					<q}f(q')$.
			\end{enumerate}
		\end{itemize}
		where $X$ is any space and  $\sqsubseteq$ is its specalisation order.

We proceed in stages.

